	@Test
	void parsedSparqlRetainsTheUnboundOrderKeyAndNamesTheServingInterpreter() throws Exception {
		set("rdf4j.lmdb.nativeQueryEngine.enabled", "true");
		set(LmdbNativeKernelLowering.SCAN_SOURCES_PROPERTY, "true");
		SailRepository repository = new SailRepository(new LmdbStore(dataDirectory,
				new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(true)
						.setDirectAdjacencyEnabled(false)));
		try {
			repository.init();
			try (SailRepositoryConnection connection = repository.getConnection()) {
				ValueFactory values = connection.getValueFactory();
				IRI first = values.createIRI("urn:ordered-tier:first");
				IRI second = values.createIRI("urn:ordered-tier:second");
				connection.begin();
				for (int root = 1; root <= 16; root++) {
					IRI subject = values.createIRI("urn:packed-quote:" + root);
					connection.add(subject, first, values.createIRI("urn:packed-quote:" + (root + 100)));
					connection.add(subject, second, values.createIRI("urn:packed-quote:" + (root + 200)));
				}
				connection.commit();
			}
			long nativeBefore = LmdbNativeAggregateCompiler.COMPILED.get();
			long compiledBefore = LmdbNativeKernelExecution.COMPILED_BINDS.get();
			long interpretedBefore = LmdbNativeKernelExecution.INTERPRETED_BINDS.get();
			List<LmdbNativeDecisionTestAccess.Selected> selected = new ArrayList<>();
			try (SailRepositoryConnection connection = repository.getConnection();
					AutoCloseable capture = LmdbNativeDecisionTestAccess.captureSelections(selected)) {
				assertAnswers(QueryResults.asList(connection.prepareTupleQuery("SELECT ?s ?a ?b WHERE { "
						+ "?s <urn:ordered-tier:first> ?a . ?s <urn:ordered-tier:second> ?b "
						+ "} ORDER BY ?missing").evaluate()));
			}
			assertThat(LmdbNativeAggregateCompiler.COMPILED.get() - nativeBefore)
					.as("the ordinary SPARQL query must reach native compilation")
					.isPositive();
			assertThat(LmdbNativeKernelExecution.COMPILED_BINDS.get() - compiledBefore).isZero();
			assertThat(LmdbNativeKernelExecution.INTERPRETED_BINDS.get() - interpretedBefore).isEqualTo(1L);
			assertThat(orderedSelections(selected)).singleElement()
					.satisfies(selection -> assertThat(selection.id())
							.as("parsed ORDER BY must retain the actual interpreter identity")
							.isEqualTo(LmdbNativeAttemptMetrics.PATH_IR_KERNEL_INTERPRETED));
		} finally {
			repository.shutDown();
		}
	}

